('000000005201','Dumbbell Waiter Biceps Curl','pull','biceps','forearms,shoulders','dumbbells','beginner','',false,55,'arms','{}'::text[]),
('900000000001','Barbell Hip Thrust','hinge','glutes','hamstrings,core','barbell','intermediate','',true,92,'glutes',ARRAY['Sit on the floor with your upper back against a bench and a padded barbell over your hips.','Plant your feet hip-width apart with shins vertical when your hips are up.','Drive through your heels to lift your hips until your torso is parallel to the floor, chin tucked.','Squeeze your glutes hard at the top for a beat, then lower with control. Do not hyperextend your lower back.']),
('900000000002','Wall Sit','squat','quads','glutes,calves','bodyweight','beginner','duration',true,70,'legs',ARRAY['Stand with your back flat against a wall and walk your feet out about two feet.','Slide down until your thighs are parallel to the floor, knees at 90° directly above your ankles.','Press your lower back into the wall and hold, breathing steadily.','To finish, push through your heels to slide back up. Keep hands off your thighs.']),
('900000000003','Cable Woodchop','core','obliques','abs,shoulders','full_gym','beginner','',true,72,'core',ARRAY['Set a cable to high-pulley height and stand side-on to the machine, feet shoulder-width apart.','Grab the handle with both hands, arms nearly straight.','Pull the handle down and across your body to the opposite hip, rotating your torso and pivoting the back foot.','Control the return along the same arc. Finish the set, then face the other way to train the opposite side.']),
('900000000004','Dumbbell Walking Lunge','squat','quads,glutes','hamstrings,core','dumbbells','intermediate','',true,80,'legs',ARRAY['Stand tall holding a dumbbell in each hand at your sides.','Step forward and lower your rear knee toward the floor, keeping your front shin vertical.','Drive through your front heel and step the rear foot through into the next lunge.','Keep your torso upright and take a beat to balance between steps.']),
('900000000005','Swimming (Freestyle)','cardio','full_body','lats,shoulders,core','bodyweight','beginner','duration,distance',false,65,'cardio',ARRAY['Swim freestyle at a steady, sustainable pace — exhale underwater, breathe every 2–3 strokes.','Keep your body long and rotate from the hips with each stroke.','Use intervals (e.g. 4×100m with 30s rest) to build up total distance.']),
('900000000006','Bird Dog','core','abs,lower_back','glutes,shoulders','bodyweight','beginner','',true,68,'core',ARRAY['Start on all fours with hands under shoulders and knees under hips.','Brace your core, then extend your right arm forward and left leg back until both are parallel to the floor.','Hold for a beat without letting your hips rotate or your back arch.','Return with control and switch sides. Move slowly — the goal is a perfectly still torso.']),
('900000000007','Dead Hang','mobility','forearms','lats,shoulders','bodyweight','beginner','duration',false,55,'mobility',ARRAY['Grip a pull-up bar with both hands shoulder-width apart and hang with straight arms.','Relax your shoulders and let your spine decompress — or keep shoulders packed to train grip.','Hold for time, breathing slowly. Step off before your grip fails completely.']),
('900000000008','Nordic Hamstring Curl','hinge','hamstrings','glutes,calves','bodyweight','advanced','',false,60,'legs',ARRAY['Kneel on a pad with your ankles anchored (partner, loaded bar, or foot anchor).','With hips extended and body in a straight line from knees to head, lower your torso forward as slowly as possible.','Catch yourself with your hands, push back up lightly, and pull with your hamstrings to return.','Fight the descent for as long as you can — the eccentric is the exercise.']),
('900000000009','Clamshell','mobility','abductors','glutes','bodyweight','beginner','',false,55,'glutes',ARRAY['Lie on your side with knees bent 90° and stacked, feet together, head resting on your arm.','Keeping your feet touching, lift your top knee as high as you can without rolling your pelvis back.','Pause at the top, feeling the side of your hip work, then lower slowly.','Finish the set and repeat on the other side. Add a mini-band above the knees to progress.']),
('900000000010','Curtsy Lunge','squat','glutes,quads','abductors,calves','bodyweight','intermediate','',false,58,'legs',ARRAY['Stand tall with feet hip-width apart, hands at your chest.','Step your right foot back and across behind your left leg, lowering your right knee toward the floor.','Keep your chest up and front knee tracking over the toes.','Push through your front heel to stand and switch sides. Hold dumbbells to progress.']),
('900000000011','Battle Ropes','cardio','shoulders,full_body','core,forearms','full_gym','beginner','duration',false,65,'cardio',ARRAY['Hold one rope end in each hand with a quarter-squat stance, chest up.','Whip the ropes in fast alternating waves, driving from the shoulders and bracing your core.','Work in intervals — e.g. 20–30 seconds hard, 30 seconds rest.','Mix in double waves or slams to vary the stimulus.']),
('900000000012','Sled Push (Prowler)','cardio','quads,glutes','calves,core,shoulders','full_gym','intermediate','weight,duration',false,60,'cardio',ARRAY['Load a push sled and grip the high or low handles with arms extended.','Lean into the sled with a flat back and drive it forward with powerful alternating steps.','Keep your core braced and push through the full foot each stride.','Push a set distance (e.g. 20–40m), rest, and repeat.'])
) AS v(sfx, nm, mp, pm, sm, eq, xp, tm, core, pop, mg, ins)
ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name, movement_pattern = EXCLUDED.movement_pattern,
  primary_muscles = EXCLUDED.primary_muscles, secondary_muscles = EXCLUDED.secondary_muscles,
  required_equipment = EXCLUDED.required_equipment, experience_level = EXCLUDED.experience_level,
  tracking_metrics = EXCLUDED.tracking_metrics, is_core = EXCLUDED.is_core,
  popularity = EXCLUDED.popularity, muscle_group = EXCLUDED.muscle_group;
